def orbit(r,c):
    pts=set()
    for rr,cc in [(r,c),(31-r,c),(r,31-c),(31-r,31-c)]:
        pts.update([(rr,cc),(cc,31-rr),(31-cc,rr),(31-rr,31-cc)])
    return {(rr,cc) for rr,cc in pts if 0<=rr<30 and 0<=cc<30}
mask=[(r,c) for r in range(30) for c in range(30) if a[r][c]==6]
from collections import Counter
